'use client';

/**
 * RoadmapView.jsx
 *
 * Renders the prerequisite course graph for a selected goal using @xyflow/react.
 *
 * ⚠ SAMPLE PREVIEW ONLY — the data here is illustrative.
 *   The real prerequisite graph will be generated by the C++ algorithm backend
 *   once it is integrated. Node positions and edges are manually set for demo purposes.
 */
import { useCallback } from 'react';
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
  addEdge,
  MarkerType,
} from '@xyflow/react';
import { GitBranch } from 'lucide-react';
import { SAMPLE_GRAPHS } from '../data/courseData';

// ── Colour config per node status ──────────────────────────
const STATUS_STYLE = {
  completed: {
    background: '#0E1D15',
    border: '1.5px solid rgba(82,217,164,0.5)',
    color: '#52D9A4',
  },
  'in-progress': {
    background: '#14132A',
    border: '1.5px solid rgba(139,124,255,0.55)',
    color: '#8B7CFF',
  },
  locked: {
    background: '#111827',
    border: '1.5px solid rgba(255,255,255,0.07)',
    color: '#55617A',
  },
};

// ── Status label map ────────────────────────────────────────
const STATUS_LABEL = {
  completed:   'Done',
  'in-progress': 'In Progress',
  locked:      'Locked',
};

// ── Convert courseData graph → ReactFlow nodes/edges ────────
function buildFlow(graphData) {
  if (!graphData) return { initialNodes: [], initialEdges: [] };

  // Arrange nodes left-to-right by level
  const levelCounts = {};
  graphData.nodes.forEach(n => {
    levelCounts[n.level] = (levelCounts[n.level] || 0) + 1;
  });

  const levelOffset = {};
  const HGAP = 200;
  const VGAP = 110;

  const initialNodes = graphData.nodes.map(n => {
    levelOffset[n.level] = (levelOffset[n.level] || 0);
    const count = levelCounts[n.level];
    const idx   = levelOffset[n.level]++;
    const x = n.level * HGAP + 30;
    const y = (idx - (count - 1) / 2) * VGAP + 180;

    return {
      id: n.id,
      position: { x, y },
      data: {
        label: (
          <div style={{ textAlign: 'center' }}>
            <div style={{ fontWeight: 600, fontSize: '0.78rem' }}>{n.label}</div>
            <div style={{ fontSize: '0.62rem', marginTop: 3, opacity: 0.7 }}>
              {STATUS_LABEL[n.status]}
            </div>
          </div>
        ),
      },
      style: {
        ...STATUS_STYLE[n.status],
        borderRadius: 10,
        padding: '8px 14px',
        minWidth: 110,
        fontFamily: 'Inter, sans-serif',
        boxShadow: n.status === 'in-progress'
          ? '0 0 14px rgba(139,124,255,0.2)'
          : '0 2px 8px rgba(0,0,0,0.4)',
      },
    };
  });

  const initialEdges = graphData.edges.map((e, i) => ({
    id: `e${i}`,
    source: e.source,
    target: e.target,
    type: 'smoothstep',
    animated: false,
    style: { stroke: 'rgba(255,255,255,0.1)', strokeWidth: 1.5 },
    markerEnd: {
      type: MarkerType.ArrowClosed,
      color: 'rgba(255,255,255,0.15)',
      width: 14,
      height: 14,
    },
  }));

  return { initialNodes, initialEdges };
}

// ── Component ───────────────────────────────────────────────
export default function RoadmapView({ goalId, onSelectGoal }) {
  const graphData = goalId ? SAMPLE_GRAPHS[goalId] : null;
  const { initialNodes, initialEdges } = buildFlow(graphData);

  const [nodes, , onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  const onConnect = useCallback(
    params => setEdges(eds => addEdge(params, eds)),
    [setEdges]
  );

  // ── Empty state ─────────────────────────────────────────
  if (!goalId) {
    return (
      <div className="empty-state">
        <div className="empty-icon-ring" aria-hidden="true">
          <GitBranch size={26} strokeWidth={1.4} />
        </div>
        <div className="empty-title">No goal selected</div>
        <p className="empty-desc">
          Pick a career goal from the Overview to preview its prerequisite roadmap here.
        </p>
        <button
          className="btn btn-outline-accent"
          id="btn-go-select-goal"
          onClick={() => onSelectGoal?.()}
        >
          Select a Goal
        </button>
      </div>
    );
  }

  return (
    <div style={{ width: '100%', height: 370 }}>
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        fitView
        fitViewOptions={{ padding: 0.25 }}
        proOptions={{ hideAttribution: true }}
        nodesDraggable={false}
        nodesConnectable={false}
        elementsSelectable={false}
        colorMode="dark"
      >
        <Background color="rgba(255,255,255,0.03)" gap={22} size={1} />
        <Controls
          showInteractive={false}
          style={{
            background: '#19233A',
            border: '1px solid rgba(255,255,255,0.07)',
            borderRadius: 8,
          }}
        />
        <MiniMap
          nodeColor={n =>
            n.style?.color || '#55617A'
          }
          style={{
            background: '#0E1425',
            border: '1px solid rgba(255,255,255,0.07)',
          }}
          maskColor="rgba(11,16,32,0.75)"
        />
      </ReactFlow>
    </div>
  );
}
